// GetManyByIDs retrieves multiple Booking records by their IDs in a single query
func (r *BookingRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Booking, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Booking{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "title", "slot_start", "slot_end", "desk_id", "holds_state", "holds_total", "status", "status_entered_at", "_version" FROM booking WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Booking, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Booking{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempHoldsState sql.NullString
		var tempHoldsTotal []byte
		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)
		var tempRelDesk *types.IdentityUUID

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Title,

			&entity.SlotStart,

			&entity.SlotEnd,

			&tempRelDesk,

			&tempHoldsState,

			&tempHoldsTotal,

			&entity.Status,

			&tempStatusEnteredAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempHoldsState.Valid {
			entity.HoldsState = tempHoldsState.String
		}
		if len(tempHoldsTotal) > 0 {
			if err := unmarshalGenericJSONFieldValue(tempHoldsTotal, &entity.HoldsTotal); err != nil {
				return nil, fmt.Errorf("failed to decode JSON field holdsTotal: %w", err)
			}
		}
		if tempStatusEnteredAt != nil {
			entity.StatusEnteredAt = tempStatusEnteredAt
		}

		// Set relationship IDs from scanned FK values
		if tempRelDesk != nil {
			// Initialize pointer for optional relationship before setting ID
			entity.Desk = &types.Desk{Id: bookingUUIDPtr(*tempRelDesk)}
		}

		entityID, ok := bookingUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

